cat > guard.py <<'PY'
from langchain.agents.middleware import AgentMiddleware

class RequireConfirm(AgentMiddleware):
    def before_model(self, state, runtime):
        text = str(state['messages'][-1].content).upper()
        if 'CONFIRM' not in text:
            raise PermissionError('refused: request lacks CONFIRM')
        return None
PY

